--- a/src/triangle.cpp
+++ b/src/triangle.cpp
@@ -0,0 +1,31 @@
+#include "geometry/triangle.hpp"
+#include <cmath>
+#include <stdexcept>
+#include <iostream>
+#include <string>
+
+namespace geometry {
+
+Triangle::Triangle(double a, double b, double c) : side_a(a), side_b(b), side_c(c) {
+    if (a <= 0 || b <= 0 || c <= 0) {
+        throw std::invalid_argument("Triangle sides must be positive.");
+    }
+    // Triangle inequality check
+    if (a + b <= c || a + c <= b || b + c <= a) {
+        throw std::invalid_argument("Sides do not form a valid triangle.");
+    }
+}
+
+std::string Triangle::name() const {
+    return "triangle";
+}
+
+double Triangle::area() const {
+    // Heron's formula
+    double s = (side_a + side_b + side_c) / 2.0;
+    // Since the constructor already validated that a valid triangle can be formed,
+    // the term inside the sqrt should be non-negative.
+    return std::sqrt(s * (s - side_a) * (s - side_b) * (s - side_c));
+}
+
+} // namespace geometry

--- a/tests/triangle_test.cpp
+++ b/tests/triangle_test.cpp
@@ -0,0 +1,88 @@
+#include "gtest/gtest.h"
+#include "geometry/triangle.hpp"
+#include "geometry/registry.hpp"
+#include <stdexcept>
+#include <cmath>
+#include <string>
+
+using namespace geometry;
+
+// 測試 geometry::Triangle 類別的建構子和方法
+TEST(TriangleTest, ValidTriangle) {
+    // 3-4-5 直角三角形，面積 = 0.5 * 3 * 4 = 6.0
+    Triangle t(3.0, 4.0, 5.0);
+    EXPECT_EQ(t.name(), "triangle");
+    // 海龍公式: sqrt(s(s-a)(s-b)(s-c))
+    // s = (3+4+5)/2 = 6
+    // Area = sqrt(6 * (6-3) * (6-4) * (6-5)) = sqrt(6 * 3 * 2 * 1) = sqrt(36) = 6.0
+    EXPECT_NEAR(t.area(), 6.0, 1e-9);
+
+    // 任意三角形
+    // s = (7+8+9)/2 = 12
+    // Area = sqrt(12 * 5 * 4 * 3) = sqrt(720) approx 26.8328
+    Triangle t2(7.0, 8.0, 9.0);
+    EXPECT_NEAR(t2.area(), std::sqrt(720.0), 1e-9);
+}
+
+TEST(TriangleTest, InvalidSideLength) {
+    // 邊長為零
+    EXPECT_THROW({
+        Triangle t(0.0, 4.0, 5.0);
+    }, std::invalid_argument);
+
+    // 邊長為負數
+    EXPECT_THROW({
+        Triangle t(3.0, -4.0, 5.0);
+    }, std::invalid_argument);
+}
+
+TEST(TriangleTest, CannotFormTriangle) {
+    // 1 + 2 <= 10 (無法組成)
+    EXPECT_THROW({
+        Triangle t(1.0, 2.0, 10.0);
+    }, std::invalid_argument);
+
+    // 1 + 1 <= 2 (無法組成，退化為線段)
+    EXPECT_THROW({
+        Triangle t(1.0, 1.0, 2.0);
+    }, std::invalid_argument);
+}
+
+// 測試 geometry::parse_shape
+TEST(RegistryTest, ParseShapeValidTriangle) {
+    std::string line = "triangle 3.0 4.0 5.0";
+    auto shape = parse_shape(line);
+    ASSERT_NE(shape, nullptr);
+    EXPECT_EQ(shape->name(), "triangle");
+    // 驗證面積，確保解析後的對象是正確的
+    EXPECT_NEAR(shape->area(), 6.0, 1e-9);
+}
+
+TEST(RegistryTest, ParseShapeInvalidTriangleFormat) {
+    // 缺少邊長
+    std::string line_missing_sides = "triangle 3.0 4.0";
+    EXPECT_THROW({
+        parse_shape(line_missing_sides);
+    }, std::invalid_argument);
+
+    // 格式錯誤 (非數字)
+    std::string line_bad_format = "triangle 3.0 four 5.0";
+    EXPECT_THROW({
+        parse_shape(line_bad_format);
+    }, std::invalid_argument);
+}
+
+// 測試解析器對建構子異常的處理 (間接測試)
+TEST(RegistryTest, ParseShapeThrowsOnInvalidTriangleConstruction) {
+    // 邊長為零
+    std::string line_zero = "triangle 0.0 4.0 5.0";
+    EXPECT_THROW({
+        parse_shape(line_zero);
+    }, std::invalid_argument);
+
+    // 無法組成三角形
+    std::string line_impossible = "triangle 1.0 2.0 10.0";
+    EXPECT_THROW({
+        parse_shape(line_impossible);
+    }, std::invalid_argument);
+}

