--- a/test/test_odom_math.cpp
+++ b/test/test_odom_math.cpp
@@ -0,0 +1,150 @@
+#include "gtest/gtest.h"
+#include "amr_utils/odom_math.hpp"
+#include <cmath>
+
+using namespace amr_utils;
+
+// Helper function to compare doubles with tolerance
+void expect_pose_near(const Pose2D& expected, const Pose2D& actual, double tolerance) {
+    EXPECT_NEAR(expected.x, actual.x, tolerance);
+    EXPECT_NEAR(expected.y, actual.y, tolerance);
+    // For angles, we check if the difference is close, considering wrap-around
+    double diff = std::abs(expected.theta - actual.theta);
+    double wrapped_diff = std::min(diff, 2.0 * M_PI - diff);
+    EXPECT_NEAR(0.0, wrapped_diff, tolerance);
+}
+
+TEST(OdomMathTest, ComposeIdentity) {
+    // If b is the identity transformation (0, 0, 0), the result should be a
+    Pose2D a = {1.0, 2.0, M_PI / 4.0};
+    Pose2D b_identity = {0.0, 0.0, 0.0};
+    Pose2D result = compose(a, b_identity);
+    expect_pose_near(a, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeSimpleTranslation) {
+    // a is at origin, b is a translation of (1, 0)
+    Pose2D a = {0.0, 0.0, 0.0};
+    Pose2D b_translation = {1.0, 0.0, 0.0};
+    Pose2D expected = {1.0, 0.0, 0.0};
+    Pose2D result = compose(a, b_translation);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeSimpleRotation) {
+    // a is at origin, b is a rotation of PI/2
+    Pose2D a = {0.0, 0.0, 0.0};
+    Pose2D b_rotation = {0.0, 0.0, M_PI / 2.0};
+    Pose2D expected = {0.0, 0.0, M_PI / 2.0};
+    Pose2D result = compose(a, b_rotation);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeTranslationInRotatedFrame) {
+    // a is at (0, 0) facing 0 rad. b is (1, 0) relative to a. Result should be (1, 0).
+    Pose2D a = {0.0, 0.0, 0.0};
+    Pose2D b = {1.0, 0.0, 0.0};
+    Pose2D expected = {1.0, 0.0, 0.0};
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeTranslationPerpendicularToHeading) {
+    // a is at (0, 0) facing PI/2 (up). b is (1, 0) relative to a (i.e., 1 unit to the right of a's heading).
+    // In world frame, this should be a translation of (0, 1).
+    Pose2D a = {0.0, 0.0, M_PI / 2.0};
+    Pose2D b = {1.0, 0.0, 0.0};
+    // Expected: x = 0 + cos(pi/2)*1 - sin(pi/2)*0 = 0 + 0*1 - 1*0 = 0
+    //           y = 0 + sin(pi/2)*1 + cos(pi/2)*0 = 0 + 1*1 + 0*0 = 1
+    //           theta = pi/2 + 0 = pi/2
+    Pose2D expected = {0.0, 1.0, M_PI / 2.0};
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeTranslationInOppositeDirection) {
+    // a is at (0, 0) facing 0 rad. b is (-1, 0) relative to a. Result should be (-1, 0).
+    Pose2D a = {0.0, 0.0, 0.0};
+    Pose2D b = {-1.0, 0.0, 0.0};
+    Pose2D expected = {-1.0, 0.0, 0.0};
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeCombinedTransform) {
+    // a: (1, 1) facing PI/4
+    Pose2D a = {1.0, 1.0, M_PI / 4.0};
+    // b: (2, 0) relative to a's frame
+    Pose2D b = {2.0, 0.0, 0.0};
+
+    // Expected calculation:
+    // cos(pi/4) = sin(pi/4) = sqrt(2)/2 approx 0.7071
+    // x = 1 + (sqrt(2)/2)*2 - (sqrt(2)/2)*0 = 1 + sqrt(2) approx 2.4142
+    // y = 1 + (sqrt(2)/2)*2 + (sqrt(2)/2)*0 = 1 + sqrt(2) approx 2.4142
+    // theta = pi/4 + 0 = pi/4
+    double sqrt2 = std::sqrt(2.0);
+    Pose2D expected = {1.0 + sqrt2, 1.0 + sqrt2, M_PI / 4.0};
+    
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeWithAngleWrapAround) {
+    // a: (0, 0) facing 3*PI/2 (-PI/2)
+    Pose2D a = {0.0, 0.0, 3.0 * M_PI / 2.0};
+    // b: (0, 1) relative to a's frame (1 unit "up" in a's frame, which is world "left")
+    Pose2D b = {0.0, 1.0, 0.0};
+
+    // Expected calculation:
+    // cos(3pi/2) = 0, sin(3pi/2) = -1
+    // x = 0 + 0*0 - (-1)*1 = 1
+    // y = 0 + (-1)*0 + 0*1 = 0
+    // theta = 3pi/2 + 0 = 3pi/2 (or -pi/2)
+    Pose2D expected = {1.0, 0.0, 3.0 * M_PI / 2.0};
+    
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeWithAngleWrapAroundResult) {
+    // a: (0, 0) facing PI
+    Pose2D a = {0.0, 0.0, M_PI};
+    // b: (0, 1) relative to a's frame (1 unit "up" in a's frame, which is world "left")
+    Pose2D b = {0.0, 1.0, 0.0};
+
+    // Expected calculation:
+    // cos(pi) = -1, sin(pi) = 0
+    // x = 0 + (-1)*0 - 0*1 = 0
+    // y = 0 + 0*0 + (-1)*1 = -1
+    // theta = pi + 0 = pi
+    Pose2D expected = {0.0, -1.0, M_PI};
+    
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeWithAngleSumExceedingTwoPi) {
+    // Test angle normalization when the sum is large
+    Pose2D a = {0.0, 0.0, 2.0 * M_PI}; // Should normalize to 0
+    Pose2D b = {0.0, 0.0, M_PI / 2.0};
+    
+    // Since a.theta is 2*PI, it should behave like 0 for calculation, but the implementation uses the raw value.
+    // The implementation relies on normalize_angle(a.theta + b.theta).
+    // 2*PI + PI/2 = 5*PI/2. normalize_angle(5*PI/2) should be PI/2.
+    Pose2D expected = {0.0, 0.0, M_PI / 2.0};
+    
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}
+
+TEST(OdomMathTest, ComposeWithNegativeAngleSum) {
+    // Test angle normalization when the sum is highly negative
+    Pose2D a = {0.0, 0.0, -3.0 * M_PI}; // Should normalize to -PI
+    Pose2D b = {0.0, 0.0, -M_PI / 2.0};
+    
+    // -3*PI - PI/2 = -7*PI/2. normalize_angle(-7*PI/2) should be -3*PI/2 + 2*PI = -PI/2.
+    Pose2D expected = {0.0, 0.0, -M_PI / 2.0};
+    
+    Pose2D result = compose(a, b);
+    expect_pose_near(expected, result, 1e-9);
+}

